// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint256).max);

        vm.deal(address(this), 1 ether);

        uint256 deposit = amount % 1 ether;
        (bool sent,) = address(c).call{value: deposit}(" ");
        require(sent);

        Reverter r = new Reverter();

        uint256 forward = amount % (address(c).balance + 1);

        bool ok;
        try c.sendMoney(address(r), forward) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert in callee");
    }
    receive() external payable {
        revert("revert in callee");
    }
}
